var SE_state = { panelEl:null, fileName:'blob.h (embedded)', text:'', cues:[], filter:'', sel:-1,
                 exe:null, exeName:'', lastPatchReport:'', exeStr:null, exeStrFor:null };

function SE_parse(text){
  var cues=[], re=/unsigned char\s+(\w+)\s*\[\]\s*=\s*\{/g, m;
  while ((m=re.exec(text))){
    var name=m[1], start=re.lastIndex, end=text.indexOf('}', start);
    if (end<0) break;
    var seg=text.slice(start,end), tre=/0x([0-9A-Fa-f]{2})/g, t, toks=[], bidx=0;
    while ((t=tre.exec(seg))){ toks.push({ val:parseInt(t[1],16), cur:parseInt(t[1],16), pos:start+t.index+2, bidx:bidx }); bidx++; }
    var events=[];
    for (var i=0;i<toks.length;i+=4){ var g=toks.slice(i,i+4); events.push({ bytes:g, partial:g.length<4 }); }
    cues.push({ name:name, events:events, nbytes:toks.length });
    re.lastIndex=end;
  }
  return cues;
}
function SE_ensureLoaded(){ if (!SE_state.cues.length){ SE_state.text=SE_BLOB; SE_state.cues=SE_parse(SE_BLOB); } }
function SE_isNote(ev){ return ev.bytes.length===4 && ev.bytes[3].cur < 0x80; }
function SE_op(ev){ return ev.bytes.length===4 ? ev.bytes[3].cur : -1; }
function SE_totalLen(c){ var s=0; for (var i=0;i<c.events.length;i++) if (SE_isNote(c.events[i])) s+=c.events[i].bytes[2].cur; return s; }
function SE_cmdName(op){ var n={0xD0:'tempo',0xD2:'tone',0xD5:'vol',0xD7:'env',0xD8:'env',0xD9:'env',0xE4:'cmd',0xE5:'cmd',0xDD:'cmd',0xF6:'cmd',0xF7:'cmd',0xFE:'rest',0xFF:'END'}; return n[op]||('0x'+op.toString(16).toUpperCase()); }

