function SE_label(name){
  if (SE_LABELS[name]) return SE_LABELS[name];
  var p=name.replace(/\d+$/,'');
  return SE_LABELS[p] || '';
}
function SE_cueEdited(c){ for (var j=0;j<c.events.length;j++){ var bs=c.events[j].bytes; for (var k=0;k<bs.length;k++) if (bs[k].cur!==bs[k].val) return true; } return false; }

// stock byte signature (original values) and current bytes for a cue
function SE_stockBytes(c){ var a=[]; for (var j=0;j<c.events.length;j++) for (var k=0;k<c.events[j].bytes.length;k++) a.push(c.events[j].bytes[k].val); return a; }

// ─── Auto-lengthen cues that trigger any `indices`, scaling ngs by `ratio` ─────
function SE_autoLengthen(indices, ratio){
  SE_ensureLoaded();
  var set={}, log=[]; for (var x=0;x<indices.length;x++) set[indices[x]]=1;
  for (var i=0;i<SE_state.cues.length;i++){
    var c=SE_state.cues[i], curTone=-1;
    for (var j=0;j<c.events.length;j++){
      var e=c.events[j]; if (e.partial) continue;
      if (!SE_isNote(e)){ if (SE_op(e)===0xD2) curTone=e.bytes[2].cur; continue; }
      if (set[curTone]){
        var nn=Math.max(1, Math.min(255, Math.round(e.bytes[2].val * ratio)));
        e.bytes[2].cur = nn;
        if (e.bytes[1].val < 100) e.bytes[1].cur = 100;
        log.push({cue:c.name, tone:curTone, oldNgs:e.bytes[2].val, newNgs:nn});
      }
    }
  }
  return log;
}

// ─── blob.h export (surgical text splice) ─────────────────────────────────────
function SE_exportText(){
  var edits=[];
  for (var i=0;i<SE_state.cues.length;i++) for (var j=0;j<SE_state.cues[i].events.length;j++){
    var bs=SE_state.cues[i].events[j].bytes;
    for (var k=0;k<bs.length;k++) if (bs[k].cur!==bs[k].val) edits.push({pos:bs[k].pos, hex:bs[k].cur.toString(16).toUpperCase().padStart(2,'0')});
  }
  edits.sort(function(a,b){return b.pos-a.pos;});
  var out=SE_state.text; for (var e=0;e<edits.length;e++) out=out.slice(0,edits[e].pos)+edits[e].hex+out.slice(edits[e].pos+2);
  return out;
}
function SE_downloadBlob(){
  SE_ensureLoaded();
  var a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([SE_exportText()],{type:'text/plain'}));
  a.download=(SE_state.fileName.replace(/ \(embedded\)/,'').replace(/\.(h|c|txt)$/i,'')||'blob')+'_mod.h';
  document.body.appendChild(a); a.click(); setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(a.href);},200);
}

// ─── Save / load a sequence profile (portable edit set, survives a stock rebuild) ─
// Save writes only the bytes that differ from vanilla, keyed by cue name + byte
// index. Load re-applies them to the editor's cues (any EXE, any build) so you can
// then Patch EXE or Export blob.h. This is the "get my sounds back" path after a
// fresh build reverts everything to stock.
function SE_saveProfile(){
  SE_ensureLoaded();
  var prof={ tool:'mgs-se-profile', version:1, savedAt:new Date().toISOString(), cues:{} }, n=0;
  for (var i=0;i<SE_state.cues.length;i++){
    var c=SE_state.cues[i], ch={}, any=false;
    for (var j=0;j<c.events.length;j++) for (var k=0;k<c.events[j].bytes.length;k++){
      var b=c.events[j].bytes[k];
      if (b.cur!==b.val){ ch[b.bidx]=b.cur; any=true; }
    }
    if (any){ prof.cues[c.name]=ch; n++; }
  }
  if (!n){ alert('No edits to save (nothing differs from vanilla yet).'); return; }
  var blob=new Blob([JSON.stringify(prof,null,1)], {type:'application/json'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='se_profile.json'; document.body.appendChild(a); a.click();
  setTimeout(function(){ document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 100);
  alert('Saved '+n+' changed cue(s) to se_profile.json');
}
function SE_loadProfile(ev){
  var f=ev.target.files&&ev.target.files[0]; if(!f) return;
  var rd=new FileReader();
  rd.onload=function(){
    var prof; try { prof=JSON.parse(rd.result); } catch(e){ alert('That file is not a valid profile (JSON parse failed).'); return; }
    if (!prof || !prof.cues){ alert('That file is not an SE profile.'); return; }
    SE_ensureLoaded();
    var byName={}; for (var i=0;i<SE_state.cues.length;i++) byName[SE_state.cues[i].name]=SE_state.cues[i];
    var applied=0, changed=0, miss=[];
    for (var name in prof.cues){
      var c=byName[name]; if(!c){ miss.push(name); continue; }
      var flat=[]; for (var j=0;j<c.events.length;j++) for (var k=0;k<c.events[j].bytes.length;k++) flat.push(c.events[j].bytes[k]);
      var ch=prof.cues[name], hit=false;
      for (var bidx in ch){ var bi=parseInt(bidx,10); if (flat[bi]){ flat[bi].cur=(ch[bidx]|0)&0xFF; hit=true; } }
      if (hit){ applied++; if (SE_cueEdited(c)) changed++; }
    }
    SE_renderCues(); if (SE_state.sel>=0) SE_renderEvents();
    var msg='Loaded profile: applied '+applied+' cue(s) ('+changed+' now differ from vanilla \u2605). '
          + 'Now Patch EXE (with an EXE loaded) or Export blob.h.';
    if (miss.length) msg+='  Not in this cue set: '+miss.slice(0,6).join(', ')+(miss.length>6?'\u2026':'')+'.';
    var rep=document.getElementById('seExeReport'); if(rep) rep.textContent=msg;
    alert(msg);
  };
  rd.readAsText(f);
  ev.target.value='';   // allow re-loading the same file
}

// ─── Detect existing edits from a loaded EXE (recover changes vs vanilla) ─────
// The user only ever edits data bytes (note velocity/gate/len, D5 volume, D2 tone);
// opcodes + structure never change. So we locate each cue by its longest run of
// UNCHANGEABLE bytes, verify the rest (ignoring editable positions), then read the
// current bytes into .cur. Lets you load any build and recover all your edits.
function SE_editableMask(c){
  var m=[];
  for (var j=0;j<c.events.length;j++){
    var bs=c.events[j].bytes, op=(bs.length===4?bs[3].val:-1), note=(bs.length===4&&bs[3].val<0x80);
    for (var k=0;k<bs.length;k++){
      var edit=false;
      if (note){ if (k<3) edit=true; }          // velocity / gate / length
      else if (op===0xD5 && k===2) edit=true;   // channel volume
      else if (op===0xD2 && k===2) edit=true;   // tone / sample select
      m.push(edit);
    }
  }
  return m;
}
function SE_longestFixedRun(mask){
  var best={start:0,len:0}, s=0,l=0;
  for (var i=0;i<mask.length;i++){
    if (!mask[i]){ if(l===0)s=i; l++; if(l>best.len)best={start:s,len:l}; } else l=0;
  }
  return best;
}
function SE_detectFromExe(){
  if (!SE_state.exe){ alert('Load the game EXE first (use the "game EXE" picker).'); return; }
  SE_ensureLoaded();
  var exe=SE_state.exe;
  if (SE_state.exeStr==null || SE_state.exeStrFor!==exe){   // one-time binary string for fast indexOf
    var CH=new Array(exe.length);
    for (var i=0;i<exe.length;i++) CH[i]=String.fromCharCode(exe[i]);
    SE_state.exeStr=CH.join(''); SE_state.exeStrFor=exe;
  }
  var S=SE_state.exeStr, changed=0, found=0, amb=[], miss=[];
  for (var ci=0;ci<SE_state.cues.length;ci++){
    var c=SE_state.cues[ci], sig=SE_stockBytes(c), mask=SE_editableMask(c);
    var run=SE_longestFixedRun(mask);
    if (run.len<4){ miss.push(c.name); continue; }
    var astr=''; for (var a=0;a<run.len;a++) astr+=String.fromCharCode(sig[run.start+a]);
    var pos=-1, hits=0, from=0, idx;
    while ((idx=S.indexOf(astr, from))>=0){
      var p=idx-run.start;
      if (p>=0 && p+sig.length<=exe.length){
        var ok=true;
        for (var b=0;b<sig.length;b++){ if(!mask[b] && exe[p+b]!==sig[b]){ ok=false; break; } }
        if (ok){ hits++; pos=p; if(hits>1) break; }
      }
      from=idx+1;
    }
    if (hits===0){ miss.push(c.name); continue; }
    if (hits>1){ amb.push(c.name); continue; }
    found++; var bi=0, any=false;
    for (var j=0;j<c.events.length;j++) for (var k=0;k<c.events[j].bytes.length;k++){
      var v=exe[pos+bi]; bi++; var bb=c.events[j].bytes[k]; bb.cur=v; if(v!==bb.val) any=true;
    }
    if (any) changed++;
  }
  SE_renderCues(); if (SE_state.sel>=0) SE_renderEvents();
  var msg='Loaded current values for '+found+' cue(s) from '+(SE_state.exeName||'the EXE')+'. '
        + changed+' differ from vanilla (marked \u2605).';
  if (amb.length)  msg+='  Skipped '+amb.length+' ambiguous ('+amb.slice(0,6).join(', ')+(amb.length>6?'\u2026':'')+').';
  if (miss.length) msg+='  '+miss.length+' not located.';
  var rep=document.getElementById('seExeReport'); if(rep) rep.textContent=msg;
  alert(msg);
}

// ─── EXE patch: find each edited cue's stock signature, patch edited bytes ─────
function SE_findAll(buf, sig){
  var hits=[], n=buf.length, m=sig.length, first=sig[0];
  for (var i=0;i+m<=n;i++){
    if (buf[i]!==first) continue;
    var ok=true; for (var k=1;k<m;k++) if (buf[i+k]!==sig[k]){ ok=false; break; }
    if (ok) hits.push(i);
  }
  return hits;
}
function SE_patchExe(){
  SE_ensureLoaded();
  if (!SE_state.exe){ alert('Load the game executable first'); return; }
  var out=SE_state.exe.slice();
  var report=[], patched=0;
  for (var i=0;i<SE_state.cues.length;i++){
    var c=SE_state.cues[i]; if (!SE_cueEdited(c)) continue;
    var sig=SE_stockBytes(c);
    var hits=SE_findAll(SE_state.exe, sig);
    if (hits.length===0){ report.push('✗ '+c.name+': signature not found in EXE'); continue; }
    if (hits.length>1){ report.push('⚠ '+c.name+': '+hits.length+' matches — skipped (ambiguous)'); continue; }
    var off=hits[0];
    for (var j=0;j<c.events.length;j++){ var bs=c.events[j].bytes;
      for (var k=0;k<bs.length;k++) if (bs[k].cur!==bs[k].val) out[off+bs[k].bidx]=bs[k].cur; }
    report.push('✓ '+c.name+' @ 0x'+off.toString(16)); patched++;
  }
  SE_state.lastPatchReport=report.join('\n');
  var rep=document.getElementById('seExeReport'); if(rep) rep.textContent=SE_state.lastPatchReport;
  if (patched===0){ alert('No cues patched.\n\n'+report.join('\n')); return; }
  var a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([out],{type:'application/octet-stream'}));
  a.download=(SE_state.exeName||'game')+'_mod';
  document.body.appendChild(a); a.click(); setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(a.href);},200);
}

// ─── UI ─────────────────────────────────────────────────────────────────────
function openSeEditor(){
  SE_ensureLoaded();
  if (SE_state.panelEl){ SE_state.panelEl.style.display='flex'; SE_renderCues(); return; }
  var ov=document.createElement('div'); ov.id='seEditorPanel';
  ov.style.cssText='position:fixed;inset:0;background:rgba(10,8,14,0.97);z-index:10000;display:flex;flex-direction:column;padding:14px;font-family:monospace';
  ov.innerHTML=
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap">'+
      '<div style="font-size:13px;font-weight:bold;color:#c9f">🎛 SE Sequence Editor <span style="color:#9f7;font-size:10px;border:1px solid #4a4;border-radius:3px;padding:0 4px;margin-left:4px">build v75 · EXE patch</span></div>'+
      '<span id="seInfo" style="color:#888;font-size:10px"></span><div style="flex:1"></div>'+
      '<label style="color:#aac;font-size:10px">override blob.h <input type="file" id="seFile" accept=".h,.c,.txt" style="font-size:10px"></label>'+
      '<button id="seExport" class="btn" style="font-size:10px;padding:4px 8px;background:#2a1a3a;color:#c9f">💾 Export blob.h</button>'+
      '<button id="seSave" class="btn" style="font-size:10px;padding:4px 8px;background:#1a3a2a;color:#9fc">📥 Save profile</button>'+
      '<label class="btn" style="font-size:10px;padding:4px 8px;background:#3a2a1a;color:#fc9;cursor:pointer">📤 Load profile<input type="file" id="seLoad" accept=".json,application/json" style="display:none"></label>'+
      '<button id="seClose" class="btn" style="font-size:11px;padding:4px 10px">✕ Close</button>'+
    '</div>'+
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap;background:#160f1f;padding:5px 8px;border-radius:4px">'+
      '<span style="color:#9f7;font-size:10px;font-weight:bold">Compiled-game mode:</span>'+
      '<label style="color:#aac;font-size:10px">game EXE <input type="file" id="seExe" style="font-size:10px"></label>'+
      '<button id="sePatch" class="btn" style="font-size:10px;padding:4px 8px;background:#1a2a3a;color:#9f7" disabled>🩹 Patch &amp; Export EXE</button>'+
      '<button id="seDetect" class="btn" style="font-size:10px;padding:4px 8px;background:#3a2a1a;color:#fc9" disabled>🔍 Detect edits from EXE</button>'+
      '<span id="seExeInfo" style="color:#888;font-size:10px"></span>'+
    '</div>'+
    '<div style="color:#667;font-size:10px;margin-bottom:6px">Edit a note\'s <b>len</b> (ticks) and set <b>gate</b>=100 so the release-clamp won\'t cut it. ★ = edited. <b>Export blob.h</b> for a recompiled project; <b>Patch EXE</b> finds each edited cue\'s byte signature in the loaded executable and patches it in place.</div>'+
    '<div style="display:flex;flex:1;min-height:0;gap:8px">'+
      '<div style="width:230px;display:flex;flex-direction:column">'+
        '<input id="seFilter" placeholder="filter cues… (pdmg, pout, ninja)" style="font-size:10px;padding:3px;margin-bottom:4px;background:#160f1f;color:#ccd;border:1px solid #423">'+
        '<div id="seCueList" style="flex:1;overflow:auto;border:1px solid #322;border-radius:4px;background:#120c18"></div>'+
      '</div>'+
      '<div style="flex:1;display:flex;flex-direction:column;min-width:0">'+
        '<div id="seCueTitle" style="color:#c9f;font-size:11px;padding:2px 4px">— select a cue —</div>'+
        '<div id="seEvents" style="flex:1;overflow:auto;border:1px solid #322;border-radius:4px;background:#0e0c12"></div>'+
        '<pre id="seExeReport" style="margin:4px 0 0;max-height:90px;overflow:auto;color:#9c9;font-size:10px;white-space:pre-wrap"></pre>'+
      '</div>'+
    '</div>';
  document.body.appendChild(ov); SE_state.panelEl=ov;
  document.getElementById('seClose').onclick=function(){ ov.style.display='none'; };
  document.getElementById('seFile').onchange=SE_onFile;
  document.getElementById('seExe').onchange=SE_onExe;
  document.getElementById('seExport').onclick=SE_downloadBlob;
  document.getElementById('seSave').onclick=SE_saveProfile;
  document.getElementById('seLoad').onchange=SE_loadProfile;
  document.getElementById('sePatch').onclick=SE_patchExe;
  document.getElementById('seDetect').onclick=SE_detectFromExe;
  document.getElementById('seFilter').oninput=function(){ SE_state.filter=this.value.toLowerCase(); SE_renderCues(); };
  SE_renderInfo(); SE_renderCues();
  var rep=document.getElementById('seExeReport'); if(rep&&SE_state.lastPatchReport) rep.textContent=SE_state.lastPatchReport;
}
function SE_renderInfo(){ var el=document.getElementById('seInfo'); if(el) el.textContent=SE_state.fileName+' · '+SE_state.cues.length+' cues'; }
function SE_onFile(ev){ var f=ev.target.files&&ev.target.files[0]; if(!f)return; var rd=new FileReader();
  rd.onload=function(){ SE_state.text=rd.result; SE_state.fileName=f.name; SE_state.cues=SE_parse(rd.result); SE_state.sel=-1;
    SE_renderInfo(); SE_renderCues(); document.getElementById('seEvents').innerHTML=''; document.getElementById('seCueTitle').textContent='— select a cue —'; };
  rd.readAsText(f); }
function SE_onExe(ev){ var f=ev.target.files&&ev.target.files[0]; if(!f)return; var rd=new FileReader();
  rd.onload=function(){ SE_state.exe=new Uint8Array(rd.result); SE_state.exeName=f.name;
    document.getElementById('seExeInfo').textContent=f.name+' · '+SE_state.exe.length+' bytes';
    document.getElementById('sePatch').disabled=false;
    var d=document.getElementById('seDetect'); if(d) d.disabled=false; };
  rd.readAsArrayBuffer(f); }
function SE_renderCues(){
  if(!SE_state.panelEl) return; var h='', f=SE_state.filter;
  for (var i=0;i<SE_state.cues.length;i++){ var c=SE_state.cues[i]; if (f && c.name.toLowerCase().indexOf(f)<0 && SE_label(c.name).toLowerCase().indexOf(f)<0) continue;
    var sel=(i===SE_state.sel), star=SE_cueEdited(c)?' <span style="color:#7f7">★</span>':'';
    var lbl=SE_label(c.name);
    var lblHtml = lbl ? '<div style="color:#8a7fa0;font-size:9px;margin-top:1px">'+lbl+'</div>' : '';
    h+='<div class="seCue" data-i="'+i+'" style="cursor:pointer;padding:3px 6px;font-size:11px;color:#ccd;border-bottom:1px solid #1d1525;'+(sel?'background:#2a1a3a':'')+'">'+c.name+star+' <span style="color:#777">·'+SE_totalLen(c)+'t</span>'+lblHtml+'</div>';
  }
  var el=document.getElementById('seCueList'); el.innerHTML=h;
  var nodes=el.querySelectorAll('.seCue'); for (var k=0;k<nodes.length;k++) nodes[k].onclick=function(){ SE_state.sel=parseInt(this.getAttribute('data-i'),10); SE_renderCues(); SE_renderEvents(); };
  SE_renderInfo();
}
function SE_renderEvents(){
  var c=SE_state.cues[SE_state.sel]; if(!c)return;
  var lbl=SE_label(c.name);
  document.getElementById('seCueTitle').textContent=c.name+(lbl?('  —  '+lbl):'')+'   (total length '+SE_totalLen(c)+' ticks)';
  var h='<table style="width:100%;border-collapse:collapse;font-size:11px;color:#cdd"><tr style="position:sticky;top:0;background:#1d1228;color:#c9f;text-align:left"><th style="padding:4px 6px">#</th><th>type</th><th>note</th><th>len</th><th>gate%</th><th>vel</th><th>raw</th></tr>';
  for (var i=0;i<c.events.length;i++){ var e=c.events[i];
    if (e.partial){ h+='<tr><td>'+i+'</td><td colspan=6 style="color:#666">'+e.bytes.map(function(b){return '0x'+b.cur.toString(16);}).join(' ')+'</td></tr>'; continue; }
    var raw=e.bytes.map(function(b){var ed=b.cur!==b.val; return '<span style="color:'+(ed?'#7f7':'#557')+'">'+b.cur.toString(16).padStart(2,'0')+'</span>';}).join(' ');
    if (SE_isNote(e)) h+='<tr style="border-top:1px solid #1a1422"><td style="padding:2px 6px">'+i+'</td><td style="color:#9c9">NOTE</td><td>'+SE_inp(i,3)+'</td><td>'+SE_inp(i,2)+'</td><td>'+SE_inp(i,1)+'</td><td>'+SE_inp(i,0)+'</td><td>'+raw+'</td></tr>';
    else { var op=SE_op(e), extra=op===0xD2?(' tone='+SE_inp(i,2)):''; h+='<tr style="border-top:1px solid #1a1422;color:#99a"><td style="padding:2px 6px">'+i+'</td><td>'+SE_cmdName(op)+extra+'</td><td colspan=4 style="color:#667"></td><td>'+raw+'</td></tr>'; }
  }
  h+='</table>'; var el=document.getElementById('seEvents'); el.innerHTML=h;
  var inp=el.querySelectorAll('input[data-ev]'); for (var k=0;k<inp.length;k++) inp[k].onchange=SE_edit;
}
function SE_inp(evIdx, byteIdx){ var e=SE_state.cues[SE_state.sel].events[evIdx], v=e.bytes[byteIdx].cur;
  return '<input type="number" min="0" max="255" value="'+v+'" data-ev="'+evIdx+'" data-b="'+byteIdx+'" style="width:48px;font-size:10px;background:#160f1f;color:#dfe;border:1px solid #423">'; }
function SE_edit(){ var ev=parseInt(this.getAttribute('data-ev'),10), bi=parseInt(this.getAttribute('data-b'),10);
  var v=parseInt(this.value,10); if(isNaN(v))v=0; v=Math.max(0,Math.min(255,v)); this.value=v;
  SE_state.cues[SE_state.sel].events[ev].bytes[bi].cur=v; SE_renderEvents(); SE_renderCues(); }
